   164→func runEnableInteractive(w io.Writer, agents []agent.Agent, opts EnableOptions) error {
   165→	// Uninstall hooks for agents that were previously active but are no longer selected
   166→	if err := uninstallDeselectedAgentHooks(w, agents); err != nil {
   167→		return fmt.Errorf("failed to clean up deselected agents: %w", err)
   168→	}
   169→
   170→	// Setup agent hooks for all selected agents
   171→	for _, ag := range agents {
   172→		if _, err := setupAgentHooks(ag, opts.LocalDev, opts.ForceHooks); err != nil {
   173→			return fmt.Errorf("failed to setup %s hooks: %w", ag.Type(), err)
   174→		}
   175→	}
   176→
   177→	// Setup .entire directory
   178→	if _, err := setupEntireDirectory(); err != nil {
   179→		return fmt.Errorf("failed to setup .entire directory: %w", err)
   180→	}
   181→
   182→	// Load existing settings to preserve other options (like strategy_options.push)
   183→	settings, err := LoadEntireSettings()
   184→	if err != nil {
   185→		// If we can't load, start with defaults
   186→		settings = &EntireSettings{}
   187→	}
   188→	// Update the specific fields
   189→	settings.Enabled = true
   190→	if opts.LocalDev {
   191→		settings.LocalDev = true
   192→	}
   193→	if opts.AbsoluteGitHookPath {
   194→		settings.AbsoluteGitHookPath = true
   195→	}
   196→
   197→	// Set push_sessions option if --skip-push-sessions flag was provided
   198→	if opts.SkipPushSessions {
   199→		if settings.StrategyOptions == nil {
   200→			settings.StrategyOptions = make(map[string]interface{})
   201→		}
   202→		settings.StrategyOptions["push_sessions"] = false
   203→	}
   204→
   205→	// Determine which settings file to write to
   206→	// First run always creates settings.json (no prompt)
   207→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
   208→	if err != nil {
   209→		entireDirAbs = paths.EntireDir // Fallback to relative
   210→	}
   211→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, opts.UseLocalSettings, opts.UseProjectSettings)
   212→
   213→	if showNotification {
   214→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
   215→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
   216→	}
