   321→// uninstallDeselectedAgentHooks removes hooks for agents that were previously
   322→// installed but are not in the selected list. This handles the case where a user
   323→// re-runs `entire enable` and deselects an agent.
   324→func uninstallDeselectedAgentHooks(w io.Writer, selectedAgents []agent.Agent) error {
   325→	installedNames := GetAgentsWithHooksInstalled()
   326→	if len(installedNames) == 0 {
   327→		return nil
   328→	}
   329→
   330→	selectedSet := make(map[agent.AgentName]struct{}, len(selectedAgents))
   331→	for _, ag := range selectedAgents {
   332→		selectedSet[ag.Name()] = struct{}{}
   333→	}
   334→
   335→	var errs []error
   336→	for _, name := range installedNames {
   337→		if _, selected := selectedSet[name]; selected {
   338→			continue
   339→		}
   340→		ag, err := agent.Get(name)
   341→		if err != nil {
   342→			continue
   343→		}
   344→		hookAgent, ok := ag.(agent.HookSupport)
   345→		if !ok {
   346→			continue
   347→		}
   348→		if err := hookAgent.UninstallHooks(); err != nil {
   349→			errs = append(errs, fmt.Errorf("failed to uninstall %s hooks: %w", ag.Type(), err))
   350→		} else {
   351→			fmt.Fprintf(w, "Removed %s hooks\n", ag.Type())
   352→		}
   353→	}
   354→	return errors.Join(errs...)
   355→}
