   373→// detectOrSelectAgent tries to auto-detect agents, or prompts the user to select.
   374→// Returns the detected/selected agents and any error.
   375→//
   376→// On first run (no hooks installed):
   377→//   - Single detected agent: used automatically
   378→//   - Multiple/no detected agents: interactive multi-select prompt
   379→//
   380→// On re-run (hooks already installed):
   381→//   - Always shows the interactive multi-select
   382→//   - Pre-selects only agents that have hooks installed (respects prior deselection)
   383→//
   384→// selectFn overrides the interactive prompt for testing. When nil, the real form is used.
   385→// It receives available agent names and returns the selected names.
   386→func detectOrSelectAgent(w io.Writer, selectFn func(available []string) ([]string, error)) ([]agent.Agent, error) {
   387→	// Check for agents with hooks already installed (re-run detection)
   388→	installedAgentNames := GetAgentsWithHooksInstalled()
   389→	hasInstalledHooks := len(installedAgentNames) > 0
   390→
   391→	// Try auto-detection
   392→	detected := agent.DetectAll()
   393→
   394→	// First run: use existing auto-detect shortcuts
   395→	if !hasInstalledHooks {
   396→		switch {
   397→		case len(detected) == 1:
   398→			fmt.Fprintf(w, "Detected agent: %s\n\n", detected[0].Type())
   399→			return detected, nil
   400→
   401→		case len(detected) > 1:
   402→			agentTypes := make([]string, 0, len(detected))
   403→			for _, ag := range detected {
   404→				agentTypes = append(agentTypes, string(ag.Type()))
   405→			}
   406→			fmt.Fprintf(w, "Detected multiple agents: %s\n", strings.Join(agentTypes, ", "))
   407→			fmt.Fprintln(w)
   408→		}
   409→	}
   410→
   411→	// Check if we can prompt interactively
   412→	if !canPromptInteractively() {
   413→		if hasInstalledHooks {
   414→			// Re-run without TTY — keep currently installed agents
   415→			agents := make([]agent.Agent, 0, len(installedAgentNames))
   416→			for _, name := range installedAgentNames {
   417→				ag, err := agent.Get(name)
   418→				if err != nil {
   419→					continue
   420→				}
   421→				agents = append(agents, ag)
   422→			}
   423→			return agents, nil
   424→		}
   425→		if len(detected) > 0 {
   426→			return detected, nil
   427→		}
   428→		defaultAgent := agent.Default()
   429→		if defaultAgent == nil {
   430→			return nil, errors.New("no default agent available")
   431→		}
   432→		fmt.Fprintf(w, "Agent: %s (use --agent to change)\n\n", defaultAgent.Type())
   433→		return []agent.Agent{defaultAgent}, nil
   434→	}
   435→
   436→	if !hasInstalledHooks && len(detected) == 0 {
   437→		fmt.Fprintln(w, "No agent configuration detected (e.g., .claude, .gemini, or .opencode directory).")
   438→		fmt.Fprintln(w, "This is normal - some agents don't require a config directory.")
   439→		fmt.Fprintln(w)
   440→	}
   441→
   442→	// Build pre-selection set.
   443→	// On re-run: only pre-select agents with hooks installed (respect prior deselection).
   444→	// On first run: pre-select all detected agents.
   445→	preSelectedSet := make(map[agent.AgentName]struct{})
   446→	if hasInstalledHooks {
   447→		for _, name := range installedAgentNames {
   448→			preSelectedSet[name] = struct{}{}
   449→		}
   450→	} else {
   451→		for _, ag := range detected {
   452→			preSelectedSet[ag.Name()] = struct{}{}
   453→		}
   454→	}
   455→
   456→	// Build options from registered agents
   457→	agentNames := agent.List()
   458→	options := make([]huh.Option[string], 0, len(agentNames))
   459→	for _, name := range agentNames {
   460→		ag, err := agent.Get(name)
   461→		if err != nil {
   462→			continue
   463→		}
   464→		// Only show agents that support hooks
   465→		if _, ok := ag.(agent.HookSupport); !ok {
   466→			continue
   467→		}
   468→		opt := huh.NewOption(string(ag.Type()), string(name))
   469→		if _, isPreSelected := preSelectedSet[name]; isPreSelected {
   470→			opt = opt.Selected(true)
   471→		}
   472→		options = append(options, opt)
   473→	}
   474→
   475→	if len(options) == 0 {
   476→		return nil, errors.New("no agents with hook support available")
   477→	}
   478→
   479→	// Collect available agent names for the selector
   480→	availableNames := make([]string, 0, len(options))
   481→	for _, opt := range options {
   482→		availableNames = append(availableNames, opt.Value)
   483→	}
   484→
   485→	var selectedAgentNames []string
   486→	if selectFn != nil {
   487→		var err error
   488→		selectedAgentNames, err = selectFn(availableNames)
   489→		if err != nil {
   490→			return nil, err
   491→		}
   492→		if len(selectedAgentNames) == 0 {
   493→			return nil, errors.New("no agents selected")
   494→		}
   495→	} else {
   496→		form := NewAccessibleForm(
   497→			huh.NewGroup(
   498→				huh.NewMultiSelect[string]().
   499→					Title("Which agents are you using?").
   500→					Description("Use space to select, enter to confirm.").
   501→					Options(options...).
   502→					Validate(func(selected []string) error {
   503→						if len(selected) == 0 {
   504→							return errors.New("please select at least one agent")
   505→						}
   506→						return nil
   507→					}).
   508→					Value(&selectedAgentNames),
   509→			),
   510→		)
   511→		if err := form.Run(); err != nil {
   512→			return nil, fmt.Errorf("agent selection cancelled: %w", err)
   513→		}
   514→	}
   515→
   516→	selectedAgents := make([]agent.Agent, 0, len(selectedAgentNames))
   517→	for _, name := range selectedAgentNames {
   518→		selectedAgent, err := agent.Get(agent.AgentName(name))
   519→		if err != nil {
   520→			return nil, fmt.Errorf("failed to get selected agent %s: %w", name, err)
   521→		}
   522→		selectedAgents = append(selectedAgents, selectedAgent)
   523→	}
   524→
   525→	agentTypes := make([]string, 0, len(selectedAgents))
   526→	for _, ag := range selectedAgents {
   527→		agentTypes = append(agentTypes, string(ag.Type()))
   528→	}
   529→	fmt.Fprintf(w, "\nSelected agents: %s\n\n", strings.Join(agentTypes, ", "))
   530→	return selectedAgents, nil
   531→}
