   766→// shellCompletionComment is the comment preceding the completion line
   767→const shellCompletionComment = "# Entire CLI shell completion"
   768→
   769→// errUnsupportedShell is returned when the user's shell is not supported for completion.
   770→var errUnsupportedShell = errors.New("unsupported shell")
   771→
   772→// shellCompletionTarget returns the rc file path and completion lines for the
   773→// user's current shell.
   774→func shellCompletionTarget() (shellName, rcFile, completionLine string, err error) {
   775→	home, err := os.UserHomeDir()
   776→	if err != nil {
   777→		return "", "", "", fmt.Errorf("cannot determine home directory: %w", err)
   778→	}
   779→
   780→	shell := os.Getenv("SHELL")
   781→	switch {
   782→	case strings.Contains(shell, "zsh"):
   783→		return "Zsh",
   784→			filepath.Join(home, ".zshrc"),
   785→			"autoload -Uz compinit && compinit && source <(entire completion zsh)",
   786→			nil
   787→	case strings.Contains(shell, "bash"):
   788→		bashRC := filepath.Join(home, ".bashrc")
   789→		if _, err := os.Stat(filepath.Join(home, ".bash_profile")); err == nil {
   790→			bashRC = filepath.Join(home, ".bash_profile")
   791→		}
   792→		return "Bash",
   793→			bashRC,
   794→			"source <(entire completion bash)",
   795→			nil
   796→	case strings.Contains(shell, "fish"):
   797→		return "Fish",
   798→			filepath.Join(home, ".config", "fish", "config.fish"),
   799→			"entire completion fish | source",
   800→			nil
   801→	default:
   802→		return "", "", "", errUnsupportedShell
   803→	}
   804→}
   805→
   806→// promptShellCompletion offers to add shell completion to the user's rc file.
   807→// Only prompts if completion is not already configured.
   808→func promptShellCompletion(w io.Writer) error {
   809→	shellName, rcFile, completionLine, err := shellCompletionTarget()
   810→	if err != nil {
   811→		if errors.Is(err, errUnsupportedShell) {
   812→			fmt.Fprintf(w, "Note: Shell completion not available for your shell. Supported: zsh, bash, fish.\n")
   813→			return nil
   814→		}
   815→		return fmt.Errorf("shell completion: %w", err)
   816→	}
   817→
   818→	if isCompletionConfigured(rcFile) {
   819→		fmt.Fprintf(w, "✓ Shell completion already configured in %s\n", rcFile)
   820→		return nil
   821→	}
   822→
   823→	var selected string
   824→	form := NewAccessibleForm(
   825→		huh.NewGroup(
   826→			huh.NewSelect[string]().
   827→				Title(fmt.Sprintf("Enable shell completion? (detected: %s)", shellName)).
   828→				Options(
   829→					huh.NewOption("Yes", "yes"),
   830→					huh.NewOption("No", "no"),
   831→				).
   832→				Value(&selected),
   833→		),
   834→	)
   835→
   836→	if err := form.Run(); err != nil {
   837→		//nolint:nilerr // User cancelled - not a fatal error, just skip
   838→		return nil
   839→	}
   840→
   841→	if selected != "yes" {
   842→		return nil
   843→	}
   844→
   845→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
   846→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
   847→	}
   848→
   849→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
   850→	fmt.Fprintln(w, "  Restart your shell to activate")
   851→
   852→	return nil
   853→}
   854→
   855→// isCompletionConfigured checks if shell completion is already in the rc file.
   856→func isCompletionConfigured(rcFile string) bool {
   857→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
   858→	content, err := os.ReadFile(rcFile)
   859→	if err != nil {
   860→		return false // File doesn't exist or can't read, treat as not configured
   861→	}
   862→	return strings.Contains(string(content), "entire completion")
   863→}
