   865→// appendShellCompletion adds the completion line to the rc file.
   866→func appendShellCompletion(rcFile, completionLine string) error {
   867→	if err := os.MkdirAll(filepath.Dir(rcFile), 0o700); err != nil {
   868→		return fmt.Errorf("creating directory: %w", err)
   869→	}
   870→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
   871→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
   872→	if err != nil {
   873→		return fmt.Errorf("opening file: %w", err)
   874→	}
   875→	defer f.Close()
   876→
   877→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
   878→	if err != nil {
   879→		return fmt.Errorf("writing completion: %w", err)
   880→	}
   881→	return nil
   882→}
