   938→	gitHooksInstalled := strategy.IsGitHookInstalled()
   939→	agentsWithInstalledHooks := GetAgentsWithHooksInstalled()
   940→	entireDirExists := checkEntireDirExists()
   941→
   942→	// Check if there's anything to uninstall
   943→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
   944→		shadowBranchCount == 0 && len(agentsWithInstalledHooks) == 0 {
   945→		fmt.Fprintln(w, "Entire is not installed in this repository.")
   946→		return nil
   947→	}
   948→
   949→	// Show confirmation prompt unless --force
   950→	if !force {
   951→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
   952→		if entireDirExists {
   953→			fmt.Fprintln(w, "  - .entire/ directory")
   954→		}
   955→		if gitHooksInstalled {
   956→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
   957→		}
   958→		if sessionStateCount > 0 {
   959→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
   960→		}
   961→		if shadowBranchCount > 0 {
   962→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
   963→		}
   964→		if len(agentsWithInstalledHooks) > 0 {
   965→			displayNames := make([]string, 0, len(agentsWithInstalledHooks))
   966→			for _, name := range agentsWithInstalledHooks {
   967→				if ag, err := agent.Get(name); err == nil {
   968→					displayNames = append(displayNames, string(ag.Type()))
   969→				}
   970→			}
   971→			fmt.Fprintf(w, "  - Agent hooks (%s)\n", strings.Join(displayNames, ", "))
   972→		}
   973→		fmt.Fprintln(w)
   974→
   975→		var confirmed bool
   976→		form := NewAccessibleForm(
   977→			huh.NewGroup(
   978→				huh.NewConfirm().
   979→					Title("Are you sure you want to uninstall Entire?").
   980→					Affirmative("Yes, uninstall").
   981→					Negative("Cancel").
   982→					Value(&confirmed),
   983→			),
   984→		)
   985→
   986→		if err := form.Run(); err != nil {
   987→			return fmt.Errorf("confirmation cancelled: %w", err)
   988→		}
   989→
   990→		if !confirmed {
   991→			fmt.Fprintln(w, "Uninstall cancelled.")
   992→			return nil
   993→		}
   994→	}
   995→
   996→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
   997→
   998→	// 1. Remove agent hooks (lowest risk)
   999→	if err := removeAgentHooks(w); err != nil {
  1000→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
  1001→	}
  1002→
  1003→	// 2. Remove git hooks
  1004→	removed, err := strategy.RemoveGitHook()
  1005→	if err != nil {
  1006→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
  1007→	} else if removed > 0 {
  1008→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
  1009→	}
  1010→
  1011→	// 3. Remove session state files
  1012→	statesRemoved, err := removeAllSessionStates()
  1013→	if err != nil {
  1014→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
  1015→	} else if statesRemoved > 0 {
  1016→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
  1017→	}
  1018→
  1019→	// 4. Remove .entire/ directory
  1020→	if err := removeEntireDirectory(); err != nil {
  1021→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
  1022→	} else if entireDirExists {
  1023→		fmt.Fprintln(w, "  Removed .entire directory")
  1024→	}
  1025→
  1026→	// 5. Remove shadow branches
  1027→	branchesRemoved, err := removeAllShadowBranches()
  1028→	if err != nil {
  1029→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
  1030→	} else if branchesRemoved > 0 {
  1031→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
  1032→	}
  1033→
  1034→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
  1035→	return nil
  1036→}
