  1070→// removeAgentHooks removes hooks from all agents that support hooks.
  1071→func removeAgentHooks(w io.Writer) error {
  1072→	var errs []error
  1073→	for _, name := range agent.List() {
  1074→		ag, err := agent.Get(name)
  1075→		if err != nil {
  1076→			continue
  1077→		}
  1078→		hs, ok := ag.(agent.HookSupport)
  1079→		if !ok {
  1080→			continue
  1081→		}
  1082→		wasInstalled := hs.AreHooksInstalled()
  1083→		if err := hs.UninstallHooks(); err != nil {
  1084→			errs = append(errs, err)
  1085→		} else if wasInstalled {
  1086→			fmt.Fprintf(w, "  Removed %s hooks\n", ag.Type())
  1087→		}
  1088→	}
  1089→	return errors.Join(errs...)
  1090→}
  1091→
  1092→// removeAllSessionStates removes all session state files and the directory.
  1093→func removeAllSessionStates() (int, error) {
  1094→	store, err := session.NewStateStore()
  1095→	if err != nil {
  1096→		return 0, fmt.Errorf("failed to create state store: %w", err)
  1097→	}
  1098→
  1099→	// Count states before removing
  1100→	states, err := store.List(context.Background())
  1101→	if err != nil {
  1102→		return 0, fmt.Errorf("failed to list session states: %w", err)
  1103→	}
  1104→	count := len(states)
  1105→
  1106→	// Remove the entire directory
  1107→	if err := store.RemoveAll(); err != nil {
  1108→		return 0, fmt.Errorf("failed to remove session states: %w", err)
  1109→	}
  1110→
  1111→	return count, nil
  1112→}
