  1114→// removeEntireDirectory removes the .entire directory.
  1115→func removeEntireDirectory() error {
  1116→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
  1117→	if err != nil {
  1118→		entireDirAbs = paths.EntireDir
  1119→	}
  1120→	if err := os.RemoveAll(entireDirAbs); err != nil {
  1121→		return fmt.Errorf("failed to remove .entire directory: %w", err)
  1122→	}
  1123→	return nil
  1124→}
